import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppView {
  DASHBOARD = 'DASHBOARD',
  MARZ_ROHANI = 'MARZ_ROHANI',
  ISM_E_AZAM = 'ISM_E_AZAM',
  ILM_US_SAAT = 'ILM_US_SAAT',
  SHADI_MUWAFIQAT = 'SHADI_MUWAFIQAT',
  FALNAMA = 'FALNAMA',
  ABJAD_CALC = 'ABJAD_CALC'
}

export interface AllahName {
  name: string;
  transliteration: string;
  adad: number;
  meaning: string;
}

export interface SaatInfo {
  name: string;
  planet: string;
  effect: 'Saad' | 'Nahis' | 'Mushtari' | 'Zahra' | 'Mareekh' | 'Shams' | 'Utarid' | 'Qamar' | 'Zuhal';
  description: string;
}

export interface CalculationResult {
  totalAdad: number;
  remainder: number;
  interpretation: string;
}

import { ABJAD_MAP } from '../constants';

/**
 * Calculates the total Abjad value of a string by summing mapped values of its characters.
 * Ignores spaces and unsupported characters.
 */
export const calculateAbjad = (text: string): number => {
  if (!text) return 0;

  let total = 0;
  const normalized = text.replace(/\s+/g, '');

  for (const char of normalized) {
    if (ABJAD_MAP[char]) {
      total += ABJAD_MAP[char];
    }
  }

  return total;
};

/**
 * Gets the current day of the week for calculation logic.
 */
export const getCurrentDayName = (): string => {
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  return days[new Date().getDay()];
};

