import React, { useState } from 'react';
import { calculateAbjad, getCurrentDayName } from '../utils/abjad';
import { DAY_VALUES } from '../constants';

const MarzRohani: React.FC = () => {
  const [name, setName] = useState('');
  const [motherName, setMotherName] = useState('');
  const [day, setDay] = useState(getCurrentDayName());
  const [result, setResult] = useState<{ type: string; desc: string; adad: number } | null>(null);

  const diagnose = () => {
    const nameAdad = calculateAbjad(name);
    const motherAdad = calculateAbjad(motherName);
    const dayValue = DAY_VALUES[day] || 0;

    const total = nameAdad + motherAdad + dayValue;
    const remainder = total % 3;

    let diagnosis = { type: '', desc: '', adad: total };

    if (remainder === 1) {
      diagnosis.type = 'روحانی اثر (نظرِ بد یا سحر)';
      diagnosis.desc = 'یہ مرض روحانی نوعیت کا معلوم ہوتا ہے۔ نظرِ بد یا کسی قسم کے اثرات کی وجہ سے بے چینی ہو سکتی ہے۔ صدقہ اور دعائیں اس کے لیے بہترین ہیں۔';
    } else if (remainder === 2) {
      diagnosis.type = 'جسمانی مرض';
      diagnosis.desc = 'یہ ایک خالص جسمانی عارضہ ہے۔ بہتر ہے کہ فوری طور پر ماہر معالج یا ڈاکٹر سے رجوع کیا جائے اور ادویات کا استعمال کیا جائے۔';
    } else {
      diagnosis.type = 'اعصابی کمزوری یا وہم';
      diagnosis.desc = 'یہ کوئی سنجیدہ روحانی یا جسمانی مرض نہیں بلکہ وہم یا اعصابی تناؤ ہو سکتا ہے۔ آرام کریں اور اپنی خوراک کا خیال رکھیں۔';
    }

    setResult(diagnosis);
  };

  return (
    <div className="max-w-xl mx-auto space-y-8 animate-fadeIn">
      <div className="card-gradient border border-slate-800 rounded-2xl p-6 shadow-xl">
        <h2 className="text-2xl urdu-text gold-text text-center mb-6">بیماری کی تشخیص</h2>

        <div className="space-y-4">
          <div>
            <label className="block text-right urdu-text text-slate-400 mb-2">مریض کا نام</label>
            <input 
              type="text" 
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none"
              placeholder="نام لکھیں..."
            />
          </div>

          <div>
            <label className="block text-right urdu-text text-slate-400 mb-2">والدہ کا نام</label>
            <input 
              type="text" 
              value={motherName}
              onChange={(e) => setMotherName(e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none"
              placeholder="والدہ کا نام..."
            />
          </div>

          <div>
            <label className="block text-right urdu-text text-slate-400 mb-2">دن کا انتخاب</label>
            <select 
              value={day}
              onChange={(e) => setDay(e.target.value)}
              className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-right urdu-text focus:border-amber-500 focus:outline-none"
            >
              {Object.keys(DAY_VALUES).map(d => (
                <option key={d} value={d}>{d}</option>
              ))}
            </select>
          </div>

          <button 
            onClick={diagnose}
            disabled={!name || !motherName}
            className="w-full gold-bg text-slate-900 font-bold py-4 rounded-xl urdu-text text-xl hover:opacity-90 disabled:opacity-50 transition-opacity"
          >
            تشخیص کریں
          </button>
        </div>
      </div>

      {result && (
        <div className="card-gradient border gold-border border-dashed rounded-2xl p-8 text-center animate-bounce-in">
          <div className="text-sm text-slate-400 mb-1">کل اعداد: {result.adad}</div>
