import React, { useState } from 'react';
import { calculateAbjad } from '../utils/abjad';
import { ALLAH_NAMES } from '../constants';
import { AllahName } from '../types';

const IsmEAzam: React.FC = () => {
  const [name, setName] = useState('');
  const [matches, setMatches] = useState<AllahName[]>([]);
  const [total, setTotal] = useState(0);

  const findMatches = () => {
    const adad = calculateAbjad(name);
    setTotal(adad);

    // Logic: Find names where the adad is close to or exactly matches, or find combinations.
    // For simplicity, we find the closest single matches or names with adad that divide cleanly.
    // Real logic often sums specific names to reach exact total.

    const sorted = [...ALLAH_NAMES].sort((a, b) => Math.abs(a.adad - adad) - Math.abs(b.adad - adad));
    setMatches(sorted.slice(0, 5));
  };

  return (
    <div className="max-w-2xl mx-auto space-y-8">
      <div className="card-gradient border border-slate-800 rounded-2xl p-6">
        <h2 className="text-2xl urdu-text gold-text text-center mb-6">اسم اعظم کا انتخاب</h2>

        <div className="flex flex-col md:flex-row gap-4">
          <input 
            type="text" 
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="flex-grow bg-slate-900 border border-slate-700 rounded-lg p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none"
            placeholder="اپنا نام لکھیں..."
          />
          <button 
            onClick={findMatches}
            disabled={!name}
            className="bg-amber-500 text-slate-950 font-bold px-8 py-3 rounded-lg urdu-text hover:bg-amber-400 transition-colors disabled:opacity-50"
          >
            تلاش کریں
          </button>
        </div>
        {total > 0 && <p className="text-center mt-4 text-slate-400">آپ کے نام کے اعداد: {total}</p>}
      </div>

      {matches.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {matches.map((m, idx) => (
            <div key={idx} className="bg-slate-900/50 border border-slate-800 p-6 rounded-xl text-center group hover:border-amber-500/30 transition-all">
              <div className="text-3xl urdu-text text-amber-500 mb-2">{m.name}</div>
              <div className="text-xs text-slate-500 uppercase tracking-tighter mb-2">{m.transliteration}</div>
              <div className="text-slate-300 text-sm urdu-text mb-2">{m.meaning}</div>
              <div className="text-lg font-mono text-amber-500/60">Adad: {m.adad}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default IsmEAzam;

import React, { useState, useEffect } from 'react';

interface SaatPeriod {
  start: string;
  end: string;
  planet: string;
  nature: 'نیک' | 'بد' | 'درمیانی';
  color: string;
}

const Saat: React.FC = () => {
  const [periods, setPeriods] = useState<SaatPeriod[]>([]);
  const [sunrise, setSunrise] = useState('06:00');
  const [sunset, setSunset] = useState('18:00');

  const calculateSaats = () => {
    const [srH, srM] = sunrise.split(':').map(Number);
    const [ssH, ssM] = sunset.split(':').map(Number);

    const startMin = srH * 60 + srM;
    const endMin = ssH * 60 + ssM;
    const duration = endMin - startMin;
    const hourLength = duration / 12;

    const planets = ['شمس', 'زہرہ', 'عطارد', 'قمر', 'زحل', 'مشتری', 'مریخ'];
    const natures: ('نیک' | 'بد' | 'درمیانی')[] = ['نیک', 'نیک', 'درمیانی', 'نیک', 'بد', 'نیک', 'بد'];
    const colors = ['text-yellow-400', 'text-pink-400', 'text-green-400', 'text-blue-200', 'text-gray-500', 'text-purple-400', 'text-red-500'];

    const newPeriods: SaatPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const pStart = startMin + i * hourLength;
      const pEnd = startMin + (i + 1) * hourLength;

      const formatTime = (mins: number) => {
        const h = Math.floor(mins / 60) % 24;
        const m = Math.round(mins % 60);
        return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
      };

      newPeriods.push({
        start: formatTime(pStart),
        end: formatTime(pEnd),
        planet: planets[i % planets.length],
        nature: natures[i % natures.length],
        color: colors[i % colors.length]
      });
    }
    setPeriods(newPeriods);
  };

  useEffect(() => {
    calculateSaats();
  }, []);

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <div className="card-gradient border border-slate-800 rounded-2xl p-6 flex flex-wrap gap-6 justify-center items-end">
        <div>
          <label className="block text-slate-400 text-xs mb-1">سورج نکلنے کا وقت</label>
          <input 
            type="time" 
            value={sunrise}
            onChange={(e) => setSunrise(e.target.value)}
            className="bg-slate-900 border border-slate-700 rounded p-2 text-amber-500"
          />
        </div>
        <div>
          <label className="block text-slate-400 text-xs mb-1">غروبِ آفتاب کا وقت</label>
          <input 
            type="time" 
            value={sunset}
            onChange={(e) => setSunset(e.target.value)}
            className="bg-slate-900 border border-slate-700 rounded p-2 text-amber-500"
          />
        </div>
        <button 
          onClick={calculateSaats}
          className="bg-amber-600 px-6 py-2 rounded text-white urdu-text hover:bg-amber-500"
        >
          ساعات معلوم کریں
        </button>
      </div>

      <div className="overflow-x-auto rounded-2xl border border-slate-800 shadow-2xl">
        <table className="w-full text-right urdu-text">
          <thead className="bg-slate-900 border-b border-slate-800">
            <tr>
              <th className="p-4 text-slate-400 font-light">وقت</th>
              <th className="p-4 text-slate-400 font-light">سیارہ</th>
              <th className="p-4 text-slate-400 font-light">کیفیت</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/50 bg-slate-950/50">
            {periods.map((p, idx) => (
              <tr key={idx} className="hover:bg-slate-900/40 transition-colors">
                <td className="p-4 font-mono text-sm text-slate-300">{p.start} - {p.end}</td>
                <td className={`p-4 text-lg font-bold ${p.color}`}>{p.planet}</td>
                <td className="p-4">
                  <span className={`px-3 py-1 rounded-full text-xs ${
                    p.nature === 'نیک' ? 'bg-green-500/10 text-green-400' : 
                    p.nature === 'بد' ? 'bg-red-500/10 text-red-400' : 'bg-yellow-500/10 text-yellow-400'
                  }`}>
                    {p.nature}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Saat;

