import React, { useState, useEffect, useCallback } from 'react';
import { PLANET_VALUES } from '../constants';

interface SaatHour {
  index: number;
  start: string;
  end: string;
  planet: string;
  isCurrent: boolean;
  value: number;
}

interface SaatProps {
  onUseSaat: (planet: string, value: number) => void;
}

const Saat: React.FC<SaatProps> = ({ onUseSaat }) => {
  const [location, setLocation] = useState<{lat: number, lng: number} | null>(null);
  const [city, setCity] = useState<string>('تلاش جاری ہے...');
  const [sunrise, setSunrise] = useState<string>('--:--');
  const [sunset, setSunset] = useState<string>('--:--');
  const [hours, setHours] = useState<SaatHour[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const planetsSequence = ['زحل', 'مشتری', 'مریخ', 'شمس', 'زہرہ', 'عطارد', 'قمر'];

  const getDayRegent = (dayIndex: number) => {
    // Sunday: Sun(3), Monday: Moon(6), Tuesday: Mars(2), Wednesday: Mercury(5), 
    // Thursday: Jupiter(1), Friday: Venus(4), Saturday: Saturn(0)
    const mapping: Record<number, string> = {
      0: 'شمس',
      1: 'قمر',
      2: 'مریخ',
      3: 'عطارد',
      4: 'مشتری',
      5: 'زہرہ',
      6: 'زحل'
    };
    return mapping[dayIndex];
  };

  const calculateDayHours = useCallback((sunriseStr: string, sunsetStr: string) => {
    const sr = new Date(sunriseStr);
    const ss = new Date(sunsetStr);
    const dayDuration = ss.getTime() - sr.getTime();
    const hourLength = dayDuration / 12;

    const dayIndex = new Date().getDay();
    const startPlanet = getDayRegent(dayIndex);
    let planetIdx = planetsSequence.indexOf(startPlanet);

    const now = new Date();
    const newHours: SaatHour[] = [];

    for (let i = 0; i < 12; i++) {
      const start = new Date(sr.getTime() + i * hourLength);
      const end = new Date(sr.getTime() + (i + 1) * hourLength);
      const planet = planetsSequence[planetIdx % 7];

      newHours.push({
        index: i + 1,
        start: start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        end: end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        planet,
        isCurrent: now >= start && now < end,
        value: PLANET_VALUES[planet] || 0
      });

      planetIdx++;
    }
    setHours(newHours);
  }, []);

  const fetchData = async (lat: number, lng: number) => {
    try {
      setLoading(true);
      const response = await fetch(`https://api.sunrise-sunset.org/json?lat=${lat}&lng=${lng}&date=today&formatted=0`);
      const data = await response.json();

      if (data.status === 'OK') {
        const sr = data.results.sunrise;
        const ss = data.results.sunset;

        setSunrise(new Date(sr).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
        setSunset(new Date(ss).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));

        calculateDayHours(sr, ss);
        setCity(`Latitude: ${lat.toFixed(2)}, Longitude: ${lng.toFixed(2)}`);
      } else {
        throw new Error('API Error');
      }
    } catch (err) {
      setError('ڈیٹا حاصل کرنے میں دشواری پیش آئی۔');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const { latitude, longitude } = pos.coords;
          setLocation({ lat: latitude, lng: longitude });
          fetchData(latitude, longitude);
        },
        () => {
          // Fallback to a default location (e.g., Karachi) if denied
          const karachi = { lat: 24.86, lng: 67.00 };
          setLocation(karachi);
          fetchData(karachi.lat, karachi.lng);
        }
      );
    } else {
      setError('آپ کا براؤزر لوکیشن سپورٹ نہیں کرتا۔');
    }
  }, []);

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-4">
      <div className="w-12 h-12 border-4 border-amber-500 border-t-transparent rounded-full animate-spin"></div>
      <p className="urdu-text text-amber-500">ساعات کا حساب کیا جا رہا ہے...</p>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto space-y-6 animate-fadeIn">
      {/* Header Info */}
      <div className="card-gradient border border-slate-800 rounded-2xl p-6 shadow-xl flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="text-right">
          <h2 className="urdu-text text-amber-500 text-lg font-bold">{city}</h2>
          <p className="text-slate-500 text-xs">مقام خودکار طریقے سے معلوم کیا گیا ہے</p>
        </div>
        <div className="flex gap-8 border-r border-slate-800 pr-8">
          <div className="text-center">
            <span className="block text-amber-500 text-2xl">🌅</span>
            <span className="urdu-text text-sm block">طلوع آفتاب</span>
            <span className="font-mono font-bold text-slate-300">{sunrise}</span>
          </div>
          <div className="text-center">
            <span className="block text-amber-500 text-2xl">🌇</span>
            <span className="urdu-text text-sm block">غروب آفتاب</span>
            <span className="font-mono font-bold text-slate-300">{sunset}</span>
          </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-xl text-red-400 urdu-text text-center">
          {error}
        </div>
      )}

      {/* Sa'at Table */}
      <div className="overflow-hidden rounded-2xl border border-slate-800 shadow-2xl">
        <table className="w-full text-right urdu-text border-collapse">
          <thead className="bg-slate-900 border-b border-slate-800">
            <tr>
              <th className="p-4 text-slate-400 font-light text-center">نمبر</th>
              <th className="p-4 text-slate-400 font-light">وقت (آغاز - اختتام)</th>
              <th className="p-4 text-slate-400 font-light">سیارہ (ساعت)</th>
              <th className="p-4 text-slate-400 font-light text-center">ایکشن</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/50 bg-slate-950/50">
            {hours.map((h) => (
              <tr 
                key={h.index} 
                className={`transition-colors ${h.isCurrent ? 'bg-amber-500/10 border-l-4 border-amber-500' : 'hover:bg-slate-900/40'}`}
              >
                <td className="p-4 text-center text-slate-500 font-mono">{h.index}</td>
                <td className="p-4 font-mono text-sm text-slate-300">
                  <span className="px-2 py-1 bg-slate-900 rounded">{h.start}</span> 
                  <span className="mx-2 text-amber-500/50">→</span> 
                  <span className="px-2 py-1 bg-slate-900 rounded">{h.end}</span>
                </td>
                <td className="p-4">
                  <div className="flex flex-col">
                    <span className="text-lg font-bold text-amber-500">{h.planet}</span>
                    <span className="text-[10px] text-slate-500 uppercase tracking-widest">Value: {h.value}</span>
                  </div>
                </td>
                <td className="p-4 text-center">
                  <button 
                    onClick={() => onUseSaat(h.planet, h.value)}
                    className={`px-4 py-2 rounded-lg text-sm urdu-text transition-all ${
                      h.isCurrent 
                      ? 'bg-amber-500 text-slate-950 font-bold hover:scale-105' 
                      : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-amber-500'
                    }`}
                  >
                    استعمال کریں
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="text-center p-4">
        <p className="urdu-text text-slate-600 text-xs">
          نوٹ: دن کی ساعات سورج نکلنے سے غروب تک کے وقت کو 12 حصوں میں تقسیم کر کے بنائی گئی ہیں۔
        </p>
      </div>
    </div>
  );
};

export default Saat;

import { ABJAD_MAP, PLANET_VALUES } from '../constants';

/**
 * Calculates the total Abjad value of a string by summing mapped values of its characters.
 * Ignores spaces and unsupported characters.
 */
export const calculateAbjad = (text: string): number => {
  if (!text) return 0;

  let total = 0;
  const normalized = text.replace(/\s+/g, '');

  for (const char of normalized) {
    if (ABJAD_MAP[char]) {
      total += ABJAD_MAP[char];
    }
  }

  return total;
};

/**
 * Reduces a number to its Mufrad (single digit 1-9).
 */
export const calculateMufrad = (num: number): number => {
  if (num === 0) return 0;
  // Standard digital root calculation for 1-9
  return ((num - 1) % 9) + 1;
};

/**
 * Gets the current day name in Persian/Urdu.
 */
export const getCurrentDayName = (): string => {
  const days = ['یکشنبه', 'دوشنبه', 'سه شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];
  return days[new Date().getDay()];
};

/**
 * Calculates the current planetary hour (Sa'at) and its default planet name.
 */
export const calculateCurrentSaatInfo = (sunrise: string = "06:00", sunset: string = "18:00") => {
  const now = new Date();
  const currentMinutes = now.getHours() * 60 + now.getMinutes();

  const [srH, srM] = sunrise.split(':').map(Number);
  const [ssH, ssM] = sunset.split(':').map(Number);

  const startMin = srH * 60 + srM;
  const endMin = ssH * 60 + ssM;
  const dayDuration = endMin - startMin;
  const saatLength = dayDuration / 12;

  // If before sunrise or after sunset, technically it's Night Sa'at
  const elapsed = currentMinutes - startMin;
  const index = Math.max(0, Math.floor(elapsed / saatLength)) % 12;

  const planets = ['شمس', 'زہرہ', 'عطارد', 'قمر', 'زحل', 'مشتری', 'مریخ'];
  const planetName = planets[index % planets.length];

  return {
    planetName,
    defaultValue: PLANET_VALUES[planetName] || 0
  };
};

