interface NamePair {
  name1: AllahName;
  name2: AllahName;
  sum: number;
}

const IsmEAzam: React.FC = () => {
  const [name, setName] = useState('');
  const [pairs, setPairs] = useState<NamePair[]>([]);
  const [closest, setClosest] = useState<AllahName[]>([]);
  const [total, setTotal] = useState(0);
  const [hasSearched, setHasSearched] = useState(false);

  const findMatches = () => {
    const targetAdad = calculateAbjad(name);
    setTotal(targetAdad);
    setHasSearched(true);

    // 1. Find pairs that sum exactly to targetAdad
    const foundPairs: NamePair[] = [];
    const seen = new Map<number, AllahName>();

    // We use a set to avoid duplicate pairs like (A+B) and (B+A)
    const processedPairs = new Set<string>();

    for (const n of ALLAH_NAMES) {
      const complement = targetAdad - n.adad;
      if (seen.has(complement)) {
        const other = seen.get(complement)!;
        const pairId = [n.name, other.name].sort().join('|');
        if (!processedPairs.has(pairId)) {
          foundPairs.push({
            name1: other,
            name2: n,
            sum: targetAdad
          });
          processedPairs.add(pairId);
        }
      }
      seen.set(n.adad, n);
    }

    setPairs(foundPairs);

    // 2. Find closest single matches as fallback or extra info
    const sortedSingle = [...ALLAH_NAMES].sort((a, b) => 
      Math.abs(a.adad - targetAdad) - Math.abs(b.adad - targetAdad)
    );
    setClosest(foundPairs.length === 0 ? sortedSingle.slice(0, 4) : []);
  };

  return (
