              <th className="p-4 text-slate-400 font-light text-center">انتخاب</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/50">
            {data.map((h) => (
              <tr 
                key={h.index} 
                className={`transition-all ${h.isCurrent ? 'bg-amber-500/15 border-r-4 border-amber-500 ring-1 ring-amber-500/30' : 'hover:bg-slate-900/40'}`}
              >
                <td className="p-4 text-center text-slate-500 font-mono text-sm">{h.index}</td>
                <td className="p-4 font-mono text-xs text-slate-300">
                  <div className="flex items-center gap-1 justify-end">
                    <span>{h.start}</span>
