      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-8 animate-fadeIn pb-24 px-4">
      <div className="card-gradient border border-slate-800 rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden">
