import { ABJAD_MAP, PLANET_VALUES } from '../constants';

/**
 * Calculates the total Abjad value of a string by summing mapped values of its characters.
 * Ignores spaces and unsupported characters.
 */
export const calculateAbjad = (text: string): number => {
  if (!text) return 0;

  let total = 0;
  const normalized = text.replace(/\s+/g, '');

  for (const char of normalized) {
    if (ABJAD_MAP[char]) {
      total += ABJAD_MAP[char];
    }
  }

  return total;
};

/**
 * Reduces a number to its Mufrad (single digit 1-9).
 */
export const calculateMufrad = (num: number): number => {
  if (num === 0) return 0;
  return ((num - 1) % 9) + 1;
};

/**
 * Gets the Islamic/Lunar day name. Shifting to next day at sunset.
 * Defaults to 6 PM if sunset is not provided.
 */
export const getIslamicDayInfo = (sunriseStr?: string, sunsetStr?: string) => {
  const now = new Date();
  const sr = sunriseStr ? new Date(sunriseStr) : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 6, 0, 0);
  const ss = sunsetStr ? new Date(sunsetStr) : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 18, 0, 0);

  let dayIndex = now.getDay();

  // If current time is past sunset, it's the next Islamic day
  if (now >= ss) {
    dayIndex = (dayIndex + 1) % 7;
  }

  const days = ['یکشنبه', 'دوشنبه', 'سه شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];
  return {
    name: days[dayIndex],
    index: dayIndex,
    isAfterSunset: now >= ss
  };
};

/**
 * Gets the current day name in Persian/Urdu (legacy bridge, uses Islamic logic).
 */
export const getCurrentDayName = (): string => {
  return getIslamicDayInfo().name;
};

/**
 * Chaldean sequence of planets
 */
export const PLANETS_SEQUENCE = ['زحل', 'مشتری', 'مریخ', 'شمس', 'زہرہ', 'عطارد', 'قمر'];

/**
 * Gets the regent planet of the day
 */
export const getDayRegent = (dayIndex: number): string => {
  const mapping: Record<number, string> = {
    0: 'شمس', // Sunday
    1: 'قمر', // Monday
    2: 'مریخ', // Tuesday
    3: 'عطارد', // Wednesday
    4: 'مشتری', // Thursday
    5: 'زہرہ', // Friday
    6: 'زحل'  // Saturday
  };
  return mapping[dayIndex];
};

/**
 * Robustly calculates the current planet based on current time.
 * Uses 6 AM / 6 PM approximation if sunrise/sunset not provided.
 */
export const calculateCurrentSaatInfo = (sunriseStr?: string, sunsetStr?: string) => {
  const now = new Date();

  // Sa'at logic always depends on the REGENT of the SUNRISE day.
  // Islamic day shifts at sunset, but Sa'at night sequence continues from the day's regent.
  const solarDayIndex = now.getDay(); 
  const regent = getDayRegent(solarDayIndex);

  let planetIdx = PLANETS_SEQUENCE.indexOf(regent);

  const sr = sunriseStr ? new Date(sunriseStr) : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 6, 0, 0);
  const ss = sunsetStr ? new Date(sunsetStr) : new Date(now.getFullYear(), now.getMonth(), now.getDate(), 18, 0, 0);

  const isDay = now >= sr && now < ss;

  if (isDay) {
    const dayDuration = ss.getTime() - sr.getTime();
    const hourLength = dayDuration / 12;
    const elapsed = now.getTime() - sr.getTime();
    const hourIndex = Math.floor(elapsed / hourLength);
    const planetName = PLANETS_SEQUENCE[(planetIdx + hourIndex) % 7];
    return { planetName, value: PLANET_VALUES[planetName] || 0 };
  } else {
    // Night hours start from 12th hour of day + 1
    const nightRegentStartIdx = (planetIdx + 12) % 7;
    const nextSr = new Date(sr.getTime() + 24 * 60 * 60 * 1000);
    const nightDuration = nextSr.getTime() - ss.getTime();
    const hourLength = nightDuration / 12;
    const elapsed = now < sr ? (now.getTime() + 24 * 60 * 60 * 1000 - ss.getTime()) : (now.getTime() - ss.getTime());
    const hourIndex = Math.floor(elapsed / hourLength);
    const planetName = PLANETS_SEQUENCE[(nightRegentStartIdx + hourIndex) % 7];
    return { planetName, value: PLANET_VALUES[planetName] || 0 };
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { calculateAbjad, getIslamicDayInfo, calculateCurrentSaatInfo } from '../utils/abjad';
import { DAY_VALUES, PLANET_VALUES } from '../constants';

interface MarzRohaniProps {
  initialSaat?: { planet: string; value: number } | null;
}

interface DiagnosisResult {
  type: string;
  adad: number;
  remainder: number;
  breakdown: {
    nameAdad: number;
    motherAdad: number;
    dayValue: number;
    saatValue: number;
  };
}

const MarzRohani: React.FC<MarzRohaniProps> = ({ initialSaat }) => {
  const [name, setName] = useState('');
  const [motherName, setMotherName] = useState('');
  const [day, setDay] = useState(getIslamicDayInfo().name);
  const [selectedPlanet, setSelectedPlanet] = useState('شمس');
  const [saatValue, setSaatValue] = useState<number>(PLANET_VALUES['شمس'] || 0);
  const [result, setResult] = useState<DiagnosisResult | null>(null);
  const [isAutoSync, setIsAutoSync] = useState(true);

  // Sync function to get current time data
  const syncCurrentData = useCallback(() => {
    if (!isAutoSync) return;

    const lunarDay = getIslamicDayInfo();
    const { planetName, value } = calculateCurrentSaatInfo();

    setDay(lunarDay.name);
    setSelectedPlanet(planetName);
    setSaatValue(value);
  }, [isAutoSync]);

  // Handle auto-sync on mount and on intervals
  useEffect(() => {
    if (initialSaat) {
      // If user came from Saat table, use that specific data and disable auto-sync
      setSelectedPlanet(initialSaat.planet);
      setSaatValue(initialSaat.value);
      setDay(getIslamicDayInfo().name);
      setIsAutoSync(false);
    } else {
      syncCurrentData();
      const interval = setInterval(syncCurrentData, 30000); // Check every 30 seconds
      return () => clearInterval(interval);
    }
  }, [initialSaat, syncCurrentData]);

  // Handle manual changes
  const handleDayChange = (val: string) => {
    setDay(val);
    setIsAutoSync(false);
  };

  const handlePlanetChange = (val: string) => {
    setSelectedPlanet(val);
    setSaatValue(PLANET_VALUES[val] || 0);
    setIsAutoSync(false);
  };

  const diagnose = () => {
    const nameAdad = calculateAbjad(name);
    const motherAdad = calculateAbjad(motherName);
    const dayValue = DAY_VALUES[day] || 0;

    const total = nameAdad + motherAdad + dayValue + saatValue;
    const remainder = total % 4;

    let diagnosisType = '';
    switch (remainder) {
      case 0: diagnosisType = 'جادو (Jadu)'; break;
      case 3: diagnosisType = 'جنات (Jinnat)'; break;
      case 2: diagnosisType = 'نظرِ بد (Nazar-e-Bad)'; break;
      case 1: diagnosisType = 'اندرونی بخار (Androoni Bukhar)'; break;
      default: diagnosisType = 'نامعلوم';
    }

    setResult({
      type: diagnosisType,
      adad: total,
      remainder,
      breakdown: {
        nameAdad,
        motherAdad,
        dayValue,
        saatValue
      }
    });
  };

  return (
    <div className="max-w-xl mx-auto space-y-8 animate-fadeIn pb-20">
      <div className="card-gradient border border-slate-800 rounded-3xl p-8 shadow-2xl relative">
        <div className="absolute top-4 left-4">
          <button 
            onClick={() => setIsAutoSync(!isAutoSync)}
            className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] uppercase tracking-tighter transition-all ${isAutoSync ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' : 'bg-slate-800 text-slate-500 border border-slate-700'}`}
          >
            <span className={`w-1.5 h-1.5 rounded-full ${isAutoSync ? 'bg-amber-500 animate-pulse' : 'bg-slate-600'}`}></span>
            {isAutoSync ? 'Live Sync ON' : 'Manual Mode'}
          </button>
        </div>

        <h2 className="text-2xl urdu-text gold-text text-center mb-8 underline underline-offset-8 decoration-amber-500/30">مرض روحانی یا جسمانی؟</h2>

        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">والدہ کا نام</label>
              <input 
                type="text" 
                value={motherName}
                onChange={(e) => setMotherName(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none transition-all"
                placeholder="والدہ کا نام لکھیں..."
              />
            </div>
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">مریض کا نام</label>
              <input 
                type="text" 
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none transition-all"
                placeholder="مریض کا نام لکھیں..."
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">سیارہ/ساعت منتخب کریں</label>
              <select 
                value={selectedPlanet}
