/**
 * Simple hash function to generate a numeric value from a string
 */
const hashCode = (str: string): number => {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash);
};

/**
 * Generates a 6-digit Request Code based on device fingerprints
 * Improved for mobile WebView compatibility
 */
export const getRequestCode = (): string => {
  // Safely gather fingerprint data
  const data = {
    ua: typeof navigator !== 'undefined' ? navigator.userAgent : 'unknown',
    sw: typeof screen !== 'undefined' ? screen.width : 0,
    sh: typeof screen !== 'undefined' ? screen.height : 0,
    lang: typeof navigator !== 'undefined' ? navigator.language : 'en',
    mem: typeof (navigator as any).deviceMemory !== 'undefined' ? (navigator as any).deviceMemory : 0,
    cores: typeof navigator.hardwareConcurrency !== 'undefined' ? navigator.hardwareConcurrency : 0
  };

  const fingerprint = Object.values(data).join('|');
  const hash = hashCode(fingerprint);

  // Ensure it's a 6-digit number between 100000 and 999999
  const code = (hash % 899999) + 100000;
  return code.toString();
};

/**
 * Secret algorithm to validate the key.
 * Formula: Key = ((RequestCode + 786) * 313) % 899999 + 100000
 */
export const validateActivationKey = (requestCode: string, inputKey: string): boolean => {
  if (!requestCode || !inputKey) return false;
  const reqNum = parseInt(requestCode);
  if (isNaN(reqNum)) return false;

  const expectedKey = ((reqNum + 786) * 313) % 899999 + 100000;
  return inputKey.trim() === expectedKey.toString();
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { PLANET_VALUES, PLANET_WAZIFAS, STATUS_JUDGMENTS, SAAT_STATUS_MATRIX } from '../constants';
import { SaatHour } from '../types';
import { getIslamicDayInfo } from '../utils/abjad';

interface SaatProps {
  onUseSaat: (planet: string, value: number) => void;
}

const Saat: React.FC<SaatProps> = ({ onUseSaat }) => {
  const [city, setCity] = useState<string>('مقام تلاش کیا جا رہا ہے...');
  const [sunrise, setSunrise] = useState<string>('--:--');
  const [sunset, setSunset] = useState<string>('--:--');
  const [dayName, setDayName] = useState<string>('');
  const [nextDayName, setNextDayName] = useState<string>('');
  const [dayHours, setDayHours] = useState<SaatHour[]>([]);
  const [nightHours, setNightHours] = useState<SaatHour[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedHour, setSelectedHour] = useState<SaatHour | null>(null);

  const hasFetched = useRef(false);

  const planetsSequence = ['زحل', 'مشتری', 'مریخ', 'شمس', 'زہرہ', 'عطارد', 'قمر'];

  const getDayRegent = (dayIndex: number) => {
    const mapping: Record<number, string> = {
      0: 'شمس', 1: 'قمر', 2: 'مریخ', 3: 'عطارد', 4: 'مشتری', 5: 'زہرہ', 6: 'زحل'
    };
    return mapping[dayIndex];
  };

  const calculateHours = useCallback((todaySr: string, todaySs: string, tomorrowSr: string) => {
    const sr = new Date(todaySr);
    const ss = new Date(todaySs);
    const tmSr = new Date(tomorrowSr);

    const dayDuration = ss.getTime() - sr.getTime();
    const dayHourLength = dayDuration / 12;

    const nightDuration = tmSr.getTime() - ss.getTime();
    const nightHourLength = nightDuration / 12;

    const dayIndex = sr.getDay();
    const startPlanet = getDayRegent(dayIndex);
    let planetIdx = planetsSequence.indexOf(startPlanet);

    const now = new Date();
    const newDayHours: SaatHour[] = [];
    const newNightHours: SaatHour[] = [];

    const dayStatusRow = SAAT_STATUS_MATRIX[dayIndex] || [];

    const days = ['یکشنبه', 'دوشنبه', 'سه شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'];
    setDayName(days[dayIndex]);
    setNextDayName(days[(dayIndex + 1) % 7]);

    // Day Hours
    for (let i = 0; i < 12; i++) {
      const start = new Date(sr.getTime() + i * dayHourLength);
      const end = new Date(sr.getTime() + (i + 1) * dayHourLength);
      const planet = planetsSequence[planetIdx % 7];
      const status = dayStatusRow[i] || 'معلوم نہیں';

      newDayHours.push({
        index: i + 1,
        start: start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        end: end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        planet,
        isCurrent: now >= start && now < end,
        value: PLANET_VALUES[planet] || 0,
        status,
        judgment: STATUS_JUDGMENTS[status] || 'حکم دستیاب نہیں',
        wazifa: PLANET_WAZIFAS[planet] || ''
      });
      planetIdx++;
    }

    // Night Hours
    for (let i = 0; i < 12; i++) {
      const start = new Date(ss.getTime() + i * nightHourLength);
      const end = new Date(ss.getTime() + (i + 1) * nightHourLength);
      const planet = planetsSequence[planetIdx % 7];
      const status = dayStatusRow[i + 12] || 'معلوم نہیں';

      newNightHours.push({
        index: i + 1,
        start: start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        end: end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        planet,
        isCurrent: now >= start && now < end,
        value: PLANET_VALUES[planet] || 0,
        status,
        judgment: STATUS_JUDGMENTS[status] || 'حکم دستیاب نہیں',
        wazifa: PLANET_WAZIFAS[planet] || ''
      });
      planetIdx++;
    }

    setDayHours(newDayHours);
    setNightHours(newNightHours);
  }, []);

  const fetchData = async (lat: number, lng: number) => {
    try {
      setLoading(true);
      setError(null);
      const resToday = await fetch(`https://api.sunrise-sunset.org/json?lat=${lat}&lng=${lng}&date=today&formatted=0`);
      const dataToday = await resToday.json();
      const resTomorrow = await fetch(`https://api.sunrise-sunset.org/json?lat=${lat}&lng=${lng}&date=tomorrow&formatted=0`);
      const dataTomorrow = await resTomorrow.json();

      if (dataToday.status === 'OK' && dataTomorrow.status === 'OK') {
        calculateHours(dataToday.results.sunrise, dataToday.results.sunset, dataTomorrow.results.sunrise);
        setSunrise(new Date(dataToday.results.sunrise).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
        setSunset(new Date(dataToday.results.sunset).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
        setCity(`${lat.toFixed(2)}N, ${lng.toFixed(2)}E`);
        hasFetched.current = true;
      } else {
        throw new Error('API Response Error');
      }
    } catch (err) {
      setError('انٹرنیٹ یا سرور کا مسئلہ۔ دوبارہ کوشش کریں۔');
    } finally {
      setLoading(false);
    }
  };

  const initLocation = useCallback(() => {
    if (hasFetched.current) return;

    setLoading(true);
    // Timeout for geolocation (WebView often hangs here)
    const timeoutId = setTimeout(() => {
      console.log('Geolocation timeout, using default Karachi location');
      fetchData(24.86, 67.00);
    }, 5000);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        clearTimeout(timeoutId);
        fetchData(pos.coords.latitude, pos.coords.longitude);
      },
      (err) => {
        clearTimeout(timeoutId);
        console.log('Geolocation error, using default Karachi location', err);
        fetchData(24.86, 67.00);
      },
      { enableHighAccuracy: false, timeout: 5000, maximumAge: 60000 }
    );
  }, []);

  useEffect(() => {
    initLocation();
  }, [initLocation]);

  const HourTable = ({ title, data, dayLabel }: { title: string, data: SaatHour[], dayLabel?: string }) => (
    <div className="space-y-4">
      <div className="flex flex-col items-center">
        <h3 className="text-xl urdu-text gold-text text-center border-b border-amber-500/20 pb-2">{title}</h3>
        {dayLabel && <span className="urdu-text text-amber-500/40 text-xs mt-1">{dayLabel}</span>}
      </div>
      <div className="overflow-x-auto rounded-2xl border border-slate-800 shadow-xl bg-slate-950/50">
        <table className="w-full text-right urdu-text border-collapse min-w-[600px]">
          <thead className="bg-slate-900/80 border-b border-slate-800">
            <tr>
              <th className="p-4 text-slate-400 font-light text-center w-12">#</th>
              <th className="p-4 text-slate-400 font-light text-center">وقت</th>
              <th className="p-4 text-slate-400 font-light">سیارہ</th>
              <th className="p-4 text-slate-400 font-light">حالت</th>
              <th className="p-4 text-slate-400 font-light text-center">تفصیل</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-800/50">
            {data.map((h) => (
              <tr 
                key={h.index} 
                className={`transition-all group ${h.isCurrent ? 'bg-amber-500/10 ring-1 ring-inset ring-amber-500/30' : 'hover:bg-slate-900/40 cursor-pointer'}`}
                onClick={() => setSelectedHour(h)}
              >
                <td className="p-4 text-center text-slate-500 font-mono text-sm">{h.index}</td>
                <td className="p-4 text-center font-mono text-[10px] text-slate-300">
                  <span className="block">{h.start}</span>
                  <span className="text-amber-500/40">تا</span>
                  <span className="block">{h.end}</span>
                </td>
                <td className="p-4">
                  <div className="flex flex-col">
                    <span className={`text-lg font-bold ${h.isCurrent ? 'text-amber-400' : 'text-slate-300'}`}>{h.planet}</span>
                    <span className="text-[9px] text-slate-600 uppercase tracking-tighter">Adad: {h.value}</span>
                  </div>
                </td>
                <td className="p-4">
                  <span className={`px-2 py-1 rounded text-[10px] ${
                    h.status.includes('سعد') ? 'bg-green-500/20 text-green-400' : 
                    h.status.includes('نحس') || h.status.includes('بد') ? 'bg-red-500/20 text-red-400' : 
                    'bg-amber-500/20 text-amber-400'
                  }`}>
                    {h.status}
                  </span>
                </td>
                <td className="p-4 text-center">
                  <button className="text-amber-500 hover:text-amber-400 text-xs">🔍</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-4">
      <div className="w-12 h-12 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin"></div>
      <p className="urdu-text text-xl text-amber-500 animate-pulse">ساعات مرتب کی جا رہی ہیں...</p>
      <p className="urdu-text text-xs text-slate-500">مقام اور وقت کا حساب لگایا جا رہا ہے</p>
    </div>
  );

  if (error) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-6 card-gradient rounded-3xl border border-red-500/20">
      <div className="text-6xl text-red-500">⚠️</div>
      <p className="urdu-text text-xl text-red-400">{error}</p>
      <button 
        onClick={() => { hasFetched.current = false; initLocation(); }}
        className="gold-bg text-emerald-950 px-8 py-3 rounded-xl urdu-text font-bold text-lg"
      >
        دوبارہ کوشش کریں
      </button>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto space-y-10 animate-fadeIn pb-24 px-4">
      {/* City & Times Info */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center card-gradient border border-slate-800 p-6 rounded-3xl">
        <div className="text-right">
          <h2 className="urdu-text text-amber-500 text-lg font-bold">مقام: {city}</h2>
          <button 
            onClick={() => { hasFetched.current = false; initLocation(); }}
            className="text-[9px] text-emerald-500/60 uppercase tracking-widest hover:text-amber-500 transition-colors"
          >
            [ Refresh Location ]
          </button>
        </div>
        <div className="flex justify-center gap-10">
          <div className="text-center">
            <span className="block text-amber-500/60 urdu-text text-xs">طلوع</span>
            <span className="font-mono text-xl text-slate-200">{sunrise}</span>
          </div>
          <div className="text-center">
            <span className="block text-amber-500/60 urdu-text text-xs">غروب</span>
            <span className="font-mono text-xl text-slate-200">{sunset}</span>
          </div>
        </div>
        <div className="text-left hidden md:block">
          <div className="bg-amber-500/10 px-4 py-2 rounded-full border border-amber-500/20 inline-block">
            <span className="urdu-text text-amber-500 text-sm">موجودہ دن: {getIslamicDayInfo().name}</span>
          </div>
        </div>
      </div>

      {/* Grid Layout */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <HourTable title="دن کی ساعات" data={dayHours} dayLabel={`دن: ${dayName}`} />
        <HourTable title="رات کی ساعات" data={nightHours} dayLabel={`رات/قمری دن: ${nextDayName}`} />
      </div>

      {/* Details Modal */}
      {selectedHour && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-sm" onClick={() => setSelectedHour(null)}>
          <div className="card-gradient border-2 gold-border border-double rounded-[2.5rem] p-8 max-w-lg w-full shadow-2xl animate-bounce-in text-right" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-start mb-6 border-b border-slate-800 pb-4">
              <button onClick={() => setSelectedHour(null)} className="text-slate-500 hover:text-white transition-colors">✕</button>
              <div className="flex flex-col items-end">
                <span className="urdu-text text-amber-500 text-2xl font-bold">{selectedHour.planet} کی ساعت</span>
                <span className="font-mono text-xs text-slate-500">{selectedHour.start} - {selectedHour.end}</span>
              </div>
            </div>

            <div className="space-y-6 text-center">
              <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800 inline-block w-full">
                <span className="block urdu-text text-slate-500 text-sm mb-1">وقت کی حالت:</span>
                <span className={`urdu-text text-xl font-bold ${
                  selectedHour.status.includes('سعد') ? 'text-green-400' : 'text-amber-500'
                }`}>{selectedHour.status}</span>
              </div>

              <div className="text-right">
                <span className="block urdu-text text-slate-500 text-sm mb-1">حکم:</span>
                <p className="urdu-text text-slate-300 leading-relaxed bg-slate-900/30 p-4 rounded-xl border border-slate-800/50 italic text-lg">
                  "{selectedHour.judgment}"
                </p>
              </div>

              <div className="bg-amber-500/5 p-4 rounded-2xl border border-amber-500/10">
                <span className="block urdu-text text-amber-500/60 text-sm mb-1 text-right">اس وقت کا وظیفہ:</span>
                <span className="urdu-text text-2xl text-amber-400 font-bold block">{selectedHour.wazifa}</span>
              </div>

              <div className="flex justify-center pt-4">
                <button 
                  onClick={() => setSelectedHour(null)}
                  className="w-full max-w-[200px] border border-slate-700 text-slate-400 font-bold py-3 rounded-xl urdu-text text-lg hover:bg-slate-800 transition-all"
                >
                  بند کریں
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Saat;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { calculateAbjad, calculateCurrentSaatInfo, getCurrentDayName } from '../utils/abjad';

const IstikharaAI: React.FC = () => {
  const [name, setName] = useState('');
  const [question, setQuestion] = useState('');
  const [response, setResponse] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const disclaimer = "واللہ ورسولہ اعلم (عزوجل و ﷺ) - حقیقی علم و غیب صرف اللہ تعالیٰ ہی کے پاس ہے";

  const getIstikhara = async () => {
    if (!name || !question) return;

    setLoading(true);
    setResponse(null);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const nameAdad = calculateAbjad(name);
      const { planetName } = calculateCurrentSaatInfo();
      const day = getCurrentDayName();

      const prompt = `
        You are a Spiritual Consultant expert in Ilm-ul-Adad (Abjad) and Islamic traditions. 
        A user named "${name}" (Abjad value: ${nameAdad}) is asking an Istikhara question: "${question}".
        Current Context:
        - Day: ${day}
        - Current Sa'at (Planetary Hour): ${planetName}

        Please provide a spiritual guidance and interpretation in Urdu (using Nastaliq-friendly phrasing). 
        The tone should be supportive, religious, and wise. 
        Incorporate the significance of their Abjad number and the current planetary hour into the response.
        Keep the response concise but profound (around 150-200 words).
        Return ONLY the response in Urdu text.
      `;

      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          temperature: 0.7,
          topP: 0.9,
        }
      });

      if (result.text) {
        setResponse(result.text);
      } else {
        throw new Error('No response from AI');
      }
    } catch (err: any) {
      console.error('Istikhara API Error:', err);
      setError('سرور سے رابطہ کرنے میں دشواری پیش آئی۔ براہ کرم اپنا انٹرنیٹ چیک کریں اور دوبارہ کوشش کریں۔');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-8 animate-fadeIn pb-24 px-4">
      <div className="card-gradient border border-slate-800 rounded-[2.5rem] p-10 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/5 blur-[80px] rounded-full -mr-20 -mt-20"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-blue-500/5 blur-[80px] rounded-full -ml-20 -mb-20"></div>

        <div className="relative z-10 text-center space-y-6">
          <h2 className="text-4xl urdu-text gold-text font-bold mb-8">روحانی استخارہ و رہنمائی</h2>

          <div className="space-y-6 max-w-2xl mx-auto">
            <div className="text-right space-y-2">
              <label className="urdu-text text-slate-400 block pr-2">آپ کا نام</label>
              <input 
                type="text" 
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-slate-900/80 border border-slate-700 rounded-2xl p-4 text-right urdu-text text-xl focus:border-amber-500 focus:outline-none transition-all"
                placeholder="نام یہاں لکھیں..."
              />
            </div>

            <div className="text-right space-y-2">
              <label className="urdu-text text-slate-400 block pr-2">آپ کا سوال یا مقصد (نیت)</label>
              <textarea 
                value={question}
                onChange={(e) => setQuestion(e.target.value)}
                rows={3}
                className="w-full bg-slate-900/80 border border-slate-700 rounded-2xl p-4 text-right urdu-text text-xl focus:border-amber-500 focus:outline-none transition-all resize-none"
                placeholder="اپنا سوال یا نیت یہاں تفصیل سے لکھیں..."
              />
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-xl text-red-400 urdu-text text-sm">
                {error}
              </div>
            )}

            <button 
              onClick={getIstikhara}
              disabled={loading || !name || !question}
              className="w-full bg-amber-500 text-slate-950 font-bold py-5 rounded-2xl urdu-text text-2xl hover:bg-amber-400 transition-all shadow-[0_0_40px_-10px_rgba(212,175,55,0.4)] disabled:opacity-30 disabled:cursor-not-allowed group"
            >
              {loading ? (
                <span className="flex items-center justify-center gap-3">
                  <div className="w-6 h-6 border-4 border-slate-900 border-t-transparent rounded-full animate-spin"></div>
                  روحانی مشاہدہ جاری ہے...
                </span>
              ) : (
                <span className="flex items-center justify-center gap-2">
                  <span>رہنمائی حاصل کریں</span>
                  <span className="group-hover:translate-x-1 transition-transform">✨</span>
                </span>
              )}
            </button>
          </div>
        </div>
      </div>

      {response && (
        <div className="card-gradient border-2 gold-border border-double rounded-[3rem] p-10 md:p-14 text-right animate-bounce-in shadow-2xl relative">
          <div className="absolute -top-6 right-12 bg-amber-500 text-slate-950 px-6 py-2 rounded-full font-bold urdu-text text-lg shadow-lg">
            روحانی جواب
          </div>

          <div className="prose prose-invert max-w-none">
            <p className="urdu-text text-2xl text-slate-200 leading-[2.8] whitespace-pre-line">
              {response}
            </p>
          </div>

          <div className="mt-12 pt-8 border-t border-slate-800/50 flex flex-col items-center gap-6">
             <p className="urdu-text text-lg italic text-amber-500/70 font-bold drop-shadow-sm text-center">
               {disclaimer}
             </p>
             <button 
               onClick={() => { setResponse(null); setQuestion(''); }}
               className="text-amber-500/60 hover:text-amber-500 transition-colors urdu-text text-sm underline"
             >
               نیا سوال پوچھیں
             </button>
          </div>
        </div>
      )}
    </div>
  );
};

