                    'bg-amber-500/20 text-amber-400'
                  }`}>
                    {h.status}
                  </span>
                </td>
                <td className="p-4 text-center">
                  <button className="text-amber-500 hover:text-amber-400 text-xs">🔍</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-4">
      <div className="w-12 h-12 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin"></div>
      <p className="urdu-text text-xl text-amber-500 animate-pulse">ساعات مرتب کی جا رہی ہیں...</p>
      <p className="urdu-text text-xs text-slate-500">مقام اور وقت کا حساب لگایا جا رہا ہے</p>
    </div>
  );

  if (error) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-6 card-gradient rounded-3xl border border-red-500/20">
      <div className="text-6xl text-red-500">⚠️</div>
      <p className="urdu-text text-xl text-red-400">{error}</p>
      <div className="flex flex-col gap-3 w-full max-w-xs">
        <button 
          onClick={() => { hasFetched.current = false; initLocation(true); }}
          className="gold-bg text-emerald-950 px-8 py-3 rounded-xl urdu-text font-bold text-lg w-full"
        >
          دوبارہ کوشش کریں
        </button>
        <button 
          onClick={() => setShowCityPicker(true)}
          className="bg-slate-800 text-amber-500 border border-amber-500/30 px-8 py-3 rounded-xl urdu-text font-bold text-lg w-full"
        >
          شہر منتخب کریں
        </button>
      </div>
    </div>
  );

  return (
    <div className="max-w-7xl mx-auto space-y-10 animate-fadeIn pb-24 px-4">
      {/* City & Times Info */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-center card-gradient border border-slate-800 p-6 rounded-3xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/5 blur-3xl rounded-full"></div>

        <div className="text-right space-y-1">
          <div className="flex items-center justify-end gap-2">
             <h2 className="urdu-text text-amber-500 text-xl font-bold">{city}</h2>
             <span className="text-lg">📍</span>
          </div>
          <div className="flex justify-end gap-3">
            <button 
              onClick={() => setShowCityPicker(true)}
              className="text-[10px] text-amber-500/60 uppercase tracking-widest hover:text-amber-500 transition-colors urdu-text"
            >
              [ شہر تبدیل کریں ]
            </button>
            <button 
              onClick={() => { hasFetched.current = false; initLocation(true); }}
              className="text-[10px] text-emerald-500/60 uppercase tracking-widest hover:text-amber-500 transition-colors"
            >
              [ Auto Locate ]
            </button>
          </div>
        </div>

        <div className="flex justify-center gap-10">
          <div className="text-center">
            <span className="block text-amber-500/60 urdu-text text-xs">طلوع</span>
            <span className="font-mono text-xl text-slate-200">{sunrise}</span>
          </div>
          <div className="text-center">
            <span className="block text-amber-500/60 urdu-text text-xs">غروب</span>
            <span className="font-mono text-xl text-slate-200">{sunset}</span>
