      {/* Grid Layout */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
        <HourTable title="دن کی ساعات" data={dayHours} dayLabel={`دن: ${dayName}`} />
        <HourTable title="رات کی ساعات" data={nightHours} dayLabel={`رات/قمری دن: ${nextDayName}`} />
