import React, { useState, useEffect, useCallback } from 'react';
import { AppView } from './types';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MarzRohani from './components/MarzRohani';
import IsmEAzam from './components/IsmEAzam';
import Saat from './components/Saat';
import ShadiMuwafiqat from './components/ShadiMuwafiqat';
import IstikharaAI from './components/IstikharaAI';
import PremiumModal from './components/PremiumModal';
import { calculateAbjad } from './utils/abjad';

const App: React.FC = () => {
  const [isUnlocked, setIsUnlocked] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallBtn, setShowInstallBtn] = useState(false);
  const [showPremiumModal, setShowPremiumModal] = useState(false);

  // Shared state for diagnosis integration
  const [preSelectedSaat, setPreSelectedSaat] = useState<{planet: string, value: number} | null>(null);

  // Shared solar data for global consistency
  const [solarData, setSolarData] = useState<{ sunrise: string; sunset: string } | null>(null);

  // State for simple Abjad calculator view
  const [calcInput, setCalcInput] = useState('');
  const [calcResult, setCalcResult] = useState(0);

  useEffect(() => {
    const unlocked = localStorage.getItem('spiritual_app_unlocked');
    if (unlocked === 'true') {
      setIsUnlocked(true);
    }

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShowInstallBtn(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setShowInstallBtn(false);
    }
    setDeferredPrompt(null);
  };

  const handleUnlock = () => {
    localStorage.setItem('spiritual_app_unlocked', 'true');
    setIsUnlocked(true);
    setShowPremiumModal(false);
  };

  const isFeaturePremium = (view: AppView) => {
    // Only 'علم الساعات' (ILM_US_SAAT) is FREE.
    return view !== AppView.ILM_US_SAAT && view !== AppView.DASHBOARD;
  };

  const handleViewSelect = (view: AppView) => {
    if (!isUnlocked && isFeaturePremium(view)) {
      setShowPremiumModal(true);
    } else {
      setCurrentView(view);
    }
  };

  const getTitle = () => {
    switch (currentView) {
      case AppView.DASHBOARD: return 'روحانی حساب کتاب و استخارہ';
      case AppView.MARZ_ROHANI: return 'تشخیصِ امراض';
      case AppView.ISM_E_AZAM: return 'انتخابِ اسمِ اعظم';
      case AppView.ILM_US_SAAT: return 'علم الساعات';
      case AppView.ABJAD_CALC: return 'ابجد کیلکولیٹر';
      case AppView.SHADI_MUWAFIQAT: return 'شادی کی موافقت';
      case AppView.ISTIKHARA_AI: return 'روحانی استخارہ';
      default: return 'ایپلی کیشن';
    }
  };

  const handleUseSaat = (planet: string, value: number) => {
    setPreSelectedSaat({ planet, value });
    setCurrentView(AppView.MARZ_ROHANI);
  };

  const renderView = () => {
    switch (currentView) {
      case AppView.DASHBOARD:
        return <Dashboard onSelect={handleViewSelect} isUnlocked={isUnlocked} />;
      case AppView.MARZ_ROHANI:
        return <MarzRohani initialSaat={preSelectedSaat} solarData={solarData} />;
      case AppView.ISM_E_AZAM:
        return <IsmEAzam />;
      case AppView.ILM_US_SAAT:
        return <Saat onUseSaat={handleUseSaat} onSolarDataUpdate={setSolarData} />;
      case AppView.ABJAD_CALC:
        return (
          <div className="max-w-xl mx-auto card-gradient border border-emerald-800 p-8 rounded-2xl animate-fadeIn premium-shadow">
            <h2 className="text-2xl urdu-text gold-text text-center mb-6">اعداد معلوم کریں</h2>
            <textarea
              className="w-full bg-emerald-950/50 border border-emerald-800 rounded-xl p-4 text-right urdu-text text-2xl focus:border-amber-500 focus:outline-none min-h-[150px] resize-none text-emerald-50"
              placeholder="یہاں عبارت لکھیں..."
              value={calcInput}
              onChange={(e) => {
                setCalcInput(e.target.value);
                setCalcResult(calculateAbjad(e.target.value));
              }}
            />
            <div className="mt-8 text-center bg-emerald-950/80 p-6 rounded-2xl border border-emerald-800">
              <span className="text-emerald-400/60 urdu-text block mb-2">کل اعداد</span>
              <span className="text-6xl font-bold text-amber-500">{calcResult}</span>
            </div>
          </div>
        );
      case AppView.SHADI_MUWAFIQAT:
        return <ShadiMuwafiqat />;
      case AppView.ISTIKHARA_AI:
        return <IstikharaAI />;
      default:
        return <Dashboard onSelect={handleViewSelect} isUnlocked={isUnlocked} />;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      onBack={() => {
        setPreSelectedSaat(null);
        setCurrentView(AppView.DASHBOARD);
      }}
      title={getTitle()}
      onInstall={showInstallBtn ? handleInstall : undefined}
    >
      {renderView()}
      {showPremiumModal && (
        <PremiumModal 
          onClose={() => setShowPremiumModal(false)} 
          onUnlock={handleUnlock}
        />
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { calculateAbjad, getIslamicDayInfo, calculateCurrentSaatInfo } from '../utils/abjad';
import { DAY_VALUES, PLANET_VALUES } from '../constants';

interface MarzRohaniProps {
  initialSaat?: { planet: string; value: number } | null;
  solarData?: { sunrise: string; sunset: string } | null;
}

interface DiagnosisResult {
  type: string;
  adad: number;
  remainder: number;
  breakdown: {
    nameAdad: number;
    motherAdad: number;
    dayValue: number;
    saatValue: number;
  };
}

const MarzRohani: React.FC<MarzRohaniProps> = ({ initialSaat, solarData }) => {
  const [name, setName] = useState('');
  const [motherName, setMotherName] = useState('');
  const [day, setDay] = useState(getIslamicDayInfo(solarData?.sunrise, solarData?.sunset).name);
  const [selectedPlanet, setSelectedPlanet] = useState('شمس');
  const [saatValue, setSaatValue] = useState<number>(PLANET_VALUES['شمس'] || 0);
  const [result, setResult] = useState<DiagnosisResult | null>(null);
  const [isAutoSync, setIsAutoSync] = useState(true);

  // Sync function to get current time data
  const syncCurrentData = useCallback(() => {
    if (!isAutoSync) return;

    // Use solarData for precise location-based calculation if available
    const lunarDay = getIslamicDayInfo(solarData?.sunrise, solarData?.sunset);
    const { planetName, value } = calculateCurrentSaatInfo(solarData?.sunrise, solarData?.sunset);

    setDay(lunarDay.name);
    setSelectedPlanet(planetName);
    setSaatValue(value);
  }, [isAutoSync, solarData]);

  // Handle auto-sync on mount and on intervals
  useEffect(() => {
    if (initialSaat) {
      // If user came from Saat table, use that specific data and disable auto-sync
      setSelectedPlanet(initialSaat.planet);
      setSaatValue(initialSaat.value);
      setDay(getIslamicDayInfo(solarData?.sunrise, solarData?.sunset).name);
      setIsAutoSync(false);
    } else {
      syncCurrentData();
      const interval = setInterval(syncCurrentData, 30000); // Check every 30 seconds
      return () => clearInterval(interval);
    }
  }, [initialSaat, syncCurrentData, solarData]);

  // Handle manual changes
  const handleDayChange = (val: string) => {
    setDay(val);
    setIsAutoSync(false);
  };

  const handlePlanetChange = (val: string) => {
    setSelectedPlanet(val);
    setSaatValue(PLANET_VALUES[val] || 0);
    setIsAutoSync(false);
  };

  const diagnose = () => {
    const nameAdad = calculateAbjad(name);
    const motherAdad = calculateAbjad(motherName);
    const dayValue = DAY_VALUES[day] || 0;

    const total = nameAdad + motherAdad + dayValue + saatValue;
    const remainder = total % 4;

    let diagnosisType = '';
    switch (remainder) {
      case 0: diagnosisType = 'جادو (Jadu)'; break;
      case 3: diagnosisType = 'جنات (Jinnat)'; break;
      case 2: diagnosisType = 'نظرِ بد (Nazar-e-Bad)'; break;
      case 1: diagnosisType = 'اندرونی بخار (Androoni Bukhar)'; break;
      default: diagnosisType = 'نامعلوم';
    }

    setResult({
      type: diagnosisType,
      adad: total,
      remainder,
      breakdown: {
        nameAdad,
        motherAdad,
        dayValue,
        saatValue
      }
    });
  };

  const disclaimer = "واللہ ورسولہ اعلم (عزوجل و ﷺ) - حقیقی علم و غیب صرف اللہ تعالیٰ ہی کے پاس ہے";

  return (
    <div className="max-w-xl mx-auto space-y-8 animate-fadeIn pb-20">
      <div className="card-gradient border border-slate-800 rounded-3xl p-8 shadow-2xl relative">
        <div className="absolute top-4 left-4">
          <button 
            onClick={() => setIsAutoSync(!isAutoSync)}
            className={`flex items-center gap-2 px-3 py-1 rounded-full text-[10px] uppercase tracking-tighter transition-all ${isAutoSync ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' : 'bg-slate-800 text-slate-500 border border-slate-700'}`}
          >
            <span className={`w-1.5 h-1.5 rounded-full ${isAutoSync ? 'bg-amber-500 animate-pulse' : 'bg-slate-600'}`}></span>
            {isAutoSync ? 'Live Sync ON' : 'Manual Mode'}
          </button>
        </div>

        <h2 className="text-2xl urdu-text gold-text text-center mb-8 underline underline-offset-8 decoration-amber-500/30">مرض روحانی یا جسمانی؟</h2>

        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">والدہ کا نام</label>
              <input 
                type="text" 
                value={motherName}
                onChange={(e) => setMotherName(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none transition-all"
                placeholder="والدہ کا نام لکھیں..."
              />
            </div>
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">مریض کا نام</label>
              <input 
                type="text" 
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-right text-xl urdu-text focus:border-amber-500 focus:outline-none transition-all"
                placeholder="مریض کا نام لکھیں..."
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-right urdu-text text-slate-400 mb-2">سیارہ/ساعت منتخب کریں</label>
              <select 
                value={selectedPlanet}
                onChange={(e) => handlePlanetChange(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-right urdu-text focus:border-amber-500 focus:outline-none transition-all appearance-none"
              >
                {Object.keys(PLANET_VALUES).map(p => (
                  <option key={p} value={p}>{p} ({PLANET_VALUES[p]})</option>
                ))}
