      desc: 'اپنے نام کے اعداد کے مطابق اسم الہیٰ', 
      icon: (
        <svg className="w-8 h-8 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
        </svg>
      )
    },
    { 
      id: AppView.SHADI_MUWAFIQAT, 
      title: 'شادی کی موافقت', 
      desc: 'ازدواجی زندگی کی مطابقت کا حساب', 
      icon: (
        <svg className="w-8 h-8 text-amber-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
        </svg>
      )
    }
  ];

  const disclaimer = "واللہ ورسولہ اعلم (عزوجل و ﷺ) - حقیقی علم و غیب صرف اللہ تعالیٰ ہی کے پاس ہے";

  return (
    <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 animate-fadeIn pb-24">
      {features.map((f, idx) => {
        const locked = !isUnlocked && isPremium(f.id);

        return (
          <button
            key={f.id}
            onClick={() => onSelect(f.id)}
            className={`card-gradient p-8 rounded-[3rem] text-right transition-all transform hover:-translate-y-2 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] group relative overflow-hidden flex flex-col items-end border-2 ${locked ? 'border-emerald-900/50' : 'border-amber-500/10'}`}
          >
            {/* Locked Overlay */}
            {locked && (
              <div className="absolute inset-0 bg-emerald-950/70 backdrop-blur-[2px] flex items-center justify-center z-20">
                <div className="bg-amber-500 p-4 rounded-full shadow-[0_0_30px_rgba(212,175,55,0.4)] border-2 border-amber-300 transform scale-110 group-hover:scale-125 transition-transform duration-500">
                  <span className="text-2xl text-emerald-950">🔒</span>
                </div>
              </div>
            )}

            <div className="absolute top-0 left-0 w-32 h-32 bg-amber-500/5 blur-[50px] rounded-full -ml-16 -mt-16"></div>

            <div className="mb-8 bg-emerald-950/50 p-5 rounded-2xl border border-emerald-800 group-hover:border-amber-500/40 transition-all self-start">
              {f.icon}
            </div>

            <h3 className="text-xl md:text-2xl urdu-text font-bold mb-4 group-hover:text-amber-500 transition-colors flex items-center gap-3">
              {f.title}
              {locked && <span className="text-amber-500/30 text-[10px] bg-amber-500/5 px-2 py-1 rounded">پریمیم</span>}
            </h3>

            <p className="text-emerald-100/60 text-base md:text-lg urdu-text leading-relaxed mb-8 text-right">
              {f.desc}
            </p>

            <div className="w-full mt-auto pt-6 border-t border-amber-500/5">
              <span className="urdu-text text-[10px] italic text-amber-500/30 text-center block leading-normal">
                {disclaimer}
              </span>
            </div>

            {!locked && (
              <div className="mt-6 flex items-center gap-2 text-amber-500/60 opacity-0 group-hover:opacity-100 transition-all transform translate-x-4 group-hover:translate-x-0">
                <span className="urdu-text text-sm">شروع کریں</span>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 19l-7-7m0 0l7-7m-7 7h18" />
                </svg>
              </div>
            )}
          </button>
        );
      })}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { AppView } from './types';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MarzRohani from './components/MarzRohani';
import IsmEAzam from './components/IsmEAzam';
import Saat from './components/Saat';
import ShadiMuwafiqat from './components/ShadiMuwafiqat';
import KhairOShar from './components/KhairOShar';
import RohaniIlaj from './components/RohaniIlaj';
import PremiumModal from './components/PremiumModal';

const App: React.FC = () => {
  const [isUnlocked, setIsUnlocked] = useState<boolean>(false);
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showInstallBtn, setShowInstallBtn] = useState(false);
  const [showPremiumModal, setShowPremiumModal] = useState(false);

  // Shared state for diagnosis integration
  const [preSelectedSaat, setPreSelectedSaat] = useState<{planet: string, value: number} | null>(null);

  // Shared solar data for global consistency
  const [solarData, setSolarData] = useState<{ sunrise: string; sunset: string } | null>(null);

  useEffect(() => {
    const unlocked = localStorage.getItem('spiritual_app_unlocked');
    if (unlocked === 'true') {
      setIsUnlocked(true);
    }

    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShowInstallBtn(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    };
  }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === 'accepted') {
      setShowInstallBtn(false);
    }
    setDeferredPrompt(null);
  };

  const handleUnlock = () => {
    localStorage.setItem('spiritual_app_unlocked', 'true');
    setIsUnlocked(true);
    setShowPremiumModal(false);
  };

  const isFeaturePremium = (view: AppView) => {
    // ILM_US_SAAT and ROHANI_ILAJ are FREE features.
    return view !== AppView.ILM_US_SAAT && view !== AppView.ROHANI_ILAJ && view !== AppView.DASHBOARD;
  };

  const handleViewSelect = (view: AppView) => {
    if (!isUnlocked && isFeaturePremium(view)) {
      setShowPremiumModal(true);
    } else {
      setCurrentView(view);
    }
  };

  const getTitle = () => {
    switch (currentView) {
      case AppView.DASHBOARD: return 'روحانی حساب کتاب و استخارہ';
      case AppView.MARZ_ROHANI: return 'تشخیصِ امراض';
      case AppView.ISM_E_AZAM: return 'انتخابِ اسمِ اعظم';
      case AppView.ILM_US_SAAT: return 'علم الساعات';
      case AppView.SHADI_MUWAFIQAT: return 'شادی کی موافقت';
      case AppView.KHAIR_O_SHAR: return 'خیر و شر کی پہچان';
      case AppView.ROHANI_ILAJ: return 'سلسلہ روحانی علاج و ہدایات';
      default: return 'ایپلی کیشن';
    }
  };

  const handleUseSaat = (planet: string, value: number) => {
    setPreSelectedSaat({ planet, value });
    setCurrentView(AppView.MARZ_ROHANI);
  };

  const renderView = () => {
    switch (currentView) {
      case AppView.DASHBOARD:
        return <Dashboard onSelect={handleViewSelect} isUnlocked={isUnlocked} />;
      case AppView.MARZ_ROHANI:
        return <MarzRohani initialSaat={preSelectedSaat} solarData={solarData} />;
      case AppView.ISM_E_AZAM:
        return <IsmEAzam />;
      case AppView.ILM_US_SAAT:
        return <Saat onUseSaat={handleUseSaat} onSolarDataUpdate={setSolarData} />;
      case AppView.SHADI_MUWAFIQAT:
        return <ShadiMuwafiqat />;
      case AppView.KHAIR_O_SHAR:
        return <KhairOShar initialSaat={preSelectedSaat} solarData={solarData} />;
      case AppView.ROHANI_ILAJ:
        return <RohaniIlaj />;
      default:
        return <Dashboard onSelect={handleViewSelect} isUnlocked={isUnlocked} />;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      onBack={() => {
        setPreSelectedSaat(null);
        setCurrentView(AppView.DASHBOARD);
      }}
      title={getTitle()}
      onInstall={showInstallBtn ? handleInstall : undefined}
    >
      {renderView()}
      {showPremiumModal && (
        <PremiumModal 
          onClose={() => setShowPremiumModal(false)} 
          onUnlock={handleUnlock}
        />
      )}
    </Layout>
  );
};

export default App;
